values
  ('11a192f4-e2bd-4674-86ea-a2e34f7472be', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', null, 'topic'::public.curated_course_node_type, 'The Sociological Study of Family', 'This opening topic frames family as a social institution, intimate relationship system, legal category, cultural ideal, and site of inequality. Students learn to move beyond personal experience toward evidence-based sociological analysis.', 0),
  ('563527ee-c7eb-4c96-9162-a333861010fc', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '11a192f4-e2bd-4674-86ea-a2e34f7472be', 'subtopic'::public.curated_course_node_type, 'Family as institution and lived experience', 'Students learn why family is both deeply personal and publicly organized by law, labor markets, culture, and policy.', 0),
  ('93374f39-87ce-464a-8b3e-f336ea0338a0', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '563527ee-c7eb-4c96-9162-a333861010fc', 'concept'::public.curated_course_node_type, 'Private troubles and public issues', null, 0),
