  ('5512dad5-4ee7-4cdf-ac73-f423f437fb22', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'da7b3905-82b0-435f-a08d-3135144f4e0e', 'concept'::public.curated_course_node_type, 'Functionalism and social reproduction', null, 0),
