  ('ba7df8ec-e4f6-48d9-9948-9473c092a086', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'da7b3905-82b0-435f-a08d-3135144f4e0e', 'concept'::public.curated_course_node_type, 'Symbolic interactionism and life-course theory', null, 2),
  ('7b86d74c-1702-4d00-8890-8d98b67d2be8', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '11a192f4-e2bd-4674-86ea-a2e34f7472be', 'subtopic'::public.curated_course_node_type, 'Evidence and family research', 'Students learn how sociologists study families through surveys, interviews, ethnography, administrative data, and historical evidence.', 2),
