  ('4ec573bd-15ec-49f6-a745-426eab83b482', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '7b86d74c-1702-4d00-8890-8d98b67d2be8', 'concept'::public.curated_course_node_type, 'Qualitative family narratives', null, 1),
  ('eb8655c4-69b3-4f09-8b4d-d9354e9eef3c', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '7b86d74c-1702-4d00-8890-8d98b67d2be8', 'concept'::public.curated_course_node_type, 'Ethics and sensitive topics', null, 2),
  ('db413992-3606-453d-8ea1-ef9067ecf8b5', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', null, 'topic'::public.curated_course_node_type, 'Defining Family, Kinship, and Household', 'Definitions of family shape law, benefits, identity, obligation, and belonging. This topic helps students see family as a contested category rather than a single natural form.', 1),
  ('8eed1fc7-27eb-4962-b220-844e89cb8222', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'db413992-3606-453d-8ea1-ef9067ecf8b5', 'subtopic'::public.curated_course_node_type, 'Family, household, and kinship', 'Students distinguish related but different concepts that are often collapsed in everyday speech.', 0),
  ('6b19948e-c38b-4272-ae00-7d3d07def94a', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '8eed1fc7-27eb-4962-b220-844e89cb8222', 'concept'::public.curated_course_node_type, 'Biological, legal, and social kin', null, 0),
  ('2594059c-d0bd-43a0-9f2f-574cb117dc09', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '8eed1fc7-27eb-4962-b220-844e89cb8222', 'concept'::public.curated_course_node_type, 'Households and co-residence', null, 1),
  ('72d9acb3-7bd7-4b50-933d-0fcffb5db7bf', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '8eed1fc7-27eb-4962-b220-844e89cb8222', 'concept'::public.curated_course_node_type, 'Chosen and fictive kin', null, 2),
  ('f6f188c1-8668-42c7-9c26-de2f5c9c56fe', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'db413992-3606-453d-8ea1-ef9067ecf8b5', 'subtopic'::public.curated_course_node_type, 'Norms and boundary-making', 'Definitions include some relationships while excluding others from recognition and resources.', 1),
  ('62d1a587-684f-4768-98d2-35f18ffdeab4', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'f6f188c1-8668-42c7-9c26-de2f5c9c56fe', 'concept'::public.curated_course_node_type, 'Nuclear-family ideal', null, 0),
  ('5c55e1c7-6b3b-41ce-b996-4d863266aafa', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'f6f188c1-8668-42c7-9c26-de2f5c9c56fe', 'concept'::public.curated_course_node_type, 'Legitimacy and stigma', null, 1),
  ('7431cb18-f932-4348-9646-9e3d323d96e3', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'f6f188c1-8668-42c7-9c26-de2f5c9c56fe', 'concept'::public.curated_course_node_type, 'State and institutional classification', null, 2),
  ('b8ffbdd5-b9db-4ca3-ad9e-24e6684d887f', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'db413992-3606-453d-8ea1-ef9067ecf8b5', 'subtopic'::public.curated_course_node_type, 'Measuring family', 'Students learn how categories used in surveys and censuses shape what researchers can see.', 2),
  ('e56c4b3f-26ea-43bd-9a25-19062ec32ef2', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'b8ffbdd5-b9db-4ca3-ad9e-24e6684d887f', 'concept'::public.curated_course_node_type, 'Household surveys', null, 0),
  ('912460b2-fb57-4146-88ae-3a8980014017', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'b8ffbdd5-b9db-4ca3-ad9e-24e6684d887f', 'concept'::public.curated_course_node_type, 'Relationship categories', null, 1),
  ('4c92a5ea-43b9-413c-9417-bca8974aac72', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'b8ffbdd5-b9db-4ca3-ad9e-24e6684d887f', 'concept'::public.curated_course_node_type, 'Limits of official data', null, 2),
  ('f7e3dd3d-76ce-4dd4-9d6a-b174c5a90edf', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', null, 'topic'::public.curated_course_node_type, 'Historical Change and Family Myths', 'Family forms have always changed, but public debate often imagines a stable traditional past. Students learn to evaluate nostalgia, myth, and evidence about family change.', 2),
