  ('597d94ec-65c2-4228-83ad-871f6c75e3d0', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'ad53b633-3653-4b22-ad6a-0ee559d1dfbb', 'concept'::public.curated_course_node_type, 'Extended households', null, 0),
  ('61e971a9-827b-4066-8074-bda1c15a6897', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'ad53b633-3653-4b22-ad6a-0ee559d1dfbb', 'concept'::public.curated_course_node_type, 'Apprenticeship, servitude, and domestic labor', null, 1),
  ('839e83aa-f887-487b-8e70-4e8d26f7a333', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'ad53b633-3653-4b22-ad6a-0ee559d1dfbb', 'concept'::public.curated_course_node_type, 'Industrialization and separate spheres', null, 2),
  ('a2fafac9-b3ce-45ee-9500-d5b22415941c', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'f7e3dd3d-76ce-4dd4-9d6a-b174c5a90edf', 'subtopic'::public.curated_course_node_type, 'The traditional family myth', 'Historical evidence complicates claims that one family model is timeless or universal.', 1),
