  ('4c4e4b92-9c7d-487e-b259-e02c028ccd69', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'f7e3dd3d-76ce-4dd4-9d6a-b174c5a90edf', 'subtopic'::public.curated_course_node_type, 'Modernization and demographic transition', 'Students connect fertility, mortality, education, and labor-market change to family transformation.', 2),
