  ('06a025fe-d394-422c-a19c-1e9eb38c8d29', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '4c4e4b92-9c7d-487e-b259-e02c028ccd69', 'concept'::public.curated_course_node_type, 'Rising life expectancy', null, 1),
  ('a7214693-1904-4822-823a-11613c52cafe', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '4c4e4b92-9c7d-487e-b259-e02c028ccd69', 'concept'::public.curated_course_node_type, 'Marriage timing and household size', null, 2),
  ('48d1d99a-a750-40c9-ac0c-25b9a45da22a', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', null, 'topic'::public.curated_course_node_type, 'Family Demography and Data Literacy', 'Family sociology depends on careful use of data. Students learn to interpret trends in marriage, divorce, fertility, cohabitation, household composition, and child wellbeing without overstating what the numbers prove.', 3);
