  ('ee34d038-b08c-456e-bfcc-42ea65986e3f', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'a087b109-8e91-4853-a460-7fe049158587', 'concept'::public.curated_course_node_type, 'No-fault divorce', null, 0),
