  ('1e424365-b399-4efc-9c71-df5119b3f615', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'a087b109-8e91-4853-a460-7fe049158587', 'concept'::public.curated_course_node_type, 'Gender roles and relationship quality', null, 2),
