  ('69aa646b-190b-4357-a812-5770890d77bc', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '688d2494-0b9d-410d-b464-0b02fa0107cf', 'concept'::public.curated_course_node_type, 'Economic consequences', null, 0),
  ('899a3f0a-d553-4d7d-bdd7-4fc6557d753e', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '688d2494-0b9d-410d-b464-0b02fa0107cf', 'concept'::public.curated_course_node_type, 'Child adjustment debates', null, 1),
