  ('d60747bf-70ae-4006-b3ca-22eb20ae15af', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '0c0d1464-3a53-457e-8924-7da936a58b98', 'concept'::public.curated_course_node_type, 'Co-parenting across households', null, 1),
  ('fa565a90-25e3-4f30-8c1a-9e630659480c', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '0c0d1464-3a53-457e-8924-7da936a58b98', 'concept'::public.curated_course_node_type, 'Step-parent roles and boundaries', null, 2),
