  ('b8188528-7830-46de-8b27-de1ad375d711', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', 'acdf5c90-5ad4-4fb4-9a5d-8053e8619508', 'subtopic'::public.curated_course_node_type, 'Parenting styles and practices', 'Students learn that parenting norms are culturally and historically situated.', 0);
