  ('32dd97e3-929c-4192-b065-c277b9c14ec5', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '9de94124-4d77-442e-b650-5cf7fb8fc34c', 'concept'::public.curated_course_node_type, 'Adverse childhood experiences', null, 2),
  ('6715924a-f0eb-4229-9301-96e6942c39ff', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', null, 'topic'::public.curated_course_node_type, 'Gender, Care Work, and Household Labor', 'Family life depends on paid and unpaid labor, much of it gendered and undervalued. Students study how care work organizes inequality inside households and across the economy.', 7),
