  ('e0719b62-bc69-4b62-a674-1c0f0f5182af', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '60fa387f-8a9a-4a4c-9a3b-952404380613', 'concept'::public.curated_course_node_type, 'Second shift', null, 0),
