  ('d79ff8a6-cdc1-499b-889b-c3402ec48427', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '6715924a-f0eb-4229-9301-96e6942c39ff', 'subtopic'::public.curated_course_node_type, 'Care work and social reproduction', 'Care work sustains people and economies but is often invisible or poorly paid.', 1),
