  ('e04f8c5a-88e2-430b-9d8e-7cd3912294fd', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', '615600aa-243c-4d21-bde6-4ae580710110', 'concept'::public.curated_course_node_type, 'Educational investment', null, 1),
