  ('b01e2036-5cef-42c8-82d5-2a4bd7c7e923', 'a2b3c4d5-6e7f-4b02-9c12-3d4e5f6a7b22', null, 'topic'::public.curated_course_node_type, 'Race, Ethnicity, Migration, and Family Life', 'Family experiences are shaped by racial formation, immigration policy, cultural tradition, discrimination, and unequal access to resources. Students learn to avoid deficit narratives and study family resilience alongside structural constraint.', 9),
